import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class AppConfigInitialConfigService implements OnModuleInit {
  private readonly logger = new AppLogger(AppConfigInitialConfigService.name);

  public constructor(private readonly configService: ConfigService) {}

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  public get appConfigCachingTtl(): number {
    return this.configService.get<number>('appConfigCachingTtl') ?? 20_000;
  }

  public get appConfigEndpoint(): string {
    return this.configService.get<string>('appConfigEndpoint') ?? '';
  }

  private checkConfiguration(): void {
    const requiredConfigs = [
      { key: 'appConfigEndpoint', value: this.appConfigEndpoint },
    ];

    /*
     * Check mandatory fields
     */
    for (const config of requiredConfigs) {
      if (!config.value) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.logger.log(
      'All required "App Config Initial Configuration" configurations are properly set',
    );
  }
}

